bash: cd /app && python3 - <<'PY'
import re
src=open('sparql_check.py').read()
ns={'re':re}
exec(src.split("def main():")[0], ns)
Parser=ns['Parser']; q_tokenize=ns['q_tokenize']; ttl_parse=ns['ttl_parse']
data=ttl_parse(open('university_graph.ttl').read())
for sub in [
'''PREFIX uni: <http://university.org/ontology/>
SELECT ?d (COUNT(DISTINCT ?s) AS ?n) WHERE {
  ?c uni:isTaughtIn ?d . ?s uni:isEnrolledIn ?c .
  OPTIONAL { ?s uni:hasGraduationDate ?g . }
} GROUP BY ?d''',
]:
    p=Parser(q_tokenize(sub)); p.prefixes['uni']='http://university.org/ontology/'
    while p.peek().text.upper()=='PREFIX': p.pos+=3
    q=p.query_body()
    for el in q['where']: print(el[0], el[1])
    sols=ns['eval_elements'](q['where'],[{}],data)
    print('sols',len(sols))
    for r in ns['eval_query'](q,data): print(r['d'][1].split('/')[-1], r['n'])
